"""Explicit effects/action review; no expansion to excluded historical units."""
import json,sys
from pathlib import Path
rows={}
def add(n,text,points,warning,case,variation,qa,term,meaning):
 rows['art-'+str(n)]=dict(simples=text,pontos=points,atencao=[warning],exemplo=case+' Variação: '+variation,prova=qa,termos=[dict(termo=term,significado=meaning)],remissoes=['https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'])
add(80,'O sursis penal suspende a execução da pena privativa nas condições legais. Não estende essa suspensão às restritivas de direitos nem à multa.', ['Objeto: pena privativa.', 'Multa e restritivas ficam fora dessa extensão.'], 'Não transformar sursis em suspensão de todas as sanções ou absolvição. Verificar o regime próprio de cada obrigação.', 'A sentença concede sursis e o candidato conclui que a multa também ficou suspensa pelo art. 80.', 'Se pergunta apenas sobre a execução da pena privativa, examinar condições do benefício, sem apagar a multa.', ['O sursis suspende automaticamente a multa? Não; o artigo exclui essa extensão.', 'Restritiva integra essa suspensão? Não; também está excluída.'],'Extensão do sursis','Delimitação das penas alcançadas pelo benefício.')
add(82,'Ao expirar o prazo sem revogação, considera-se extinta a pena privativa suspensa. Não é absolvição retroativa nem cancelamento automático das outras sanções.', ['Prazo expirado E ausência de revogação.', 'Extinção refere-se à pena privativa.'], 'Não confundir o prazo de prova do sursis com prescrição ou livramento. Os efeitos remanescentes têm regime próprio.', 'O período termina sem revogação e pergunta-se o efeito sobre a pena privativa suspensa.', 'Se houve revogação, falta uma condição da regra; não repetir a resposta de extinção.', ['Basta conceder sursis para extinguir imediatamente? Não; a regra usa o término sem revogação.', 'A regra cancela toda multa? Não; delimita a pena privativa.'],'Término do sursis','Conclusão do período de prova na hipótese legal.')
add(83,'Livramento condicional pressupõe pena privativa igual ou superior a dois anos, fração pertinente e requisitos cumulativos. O requisito de ausência de falta grave nos últimos doze meses não dispensa a avaliação do comportamento durante a execução.', ['Mais de 1/3 na hipótese do inciso I; mais da metade no II.', 'Mais de 2/3 no inciso V, com ausência de reincidência específica; distinguir vedações da LEP, como feminicídio na hipótese atual do art. 112, VI, d, após Lei 15.358, vigente em 25/3/2026, sem retroatividade gravosa.', 'Reparação ressalva efetiva impossibilidade; violência/ameaça tem requisito pessoal adicional.'], 'Fração cumprida não garante benefício. Súmula 441/STJ: falta grave não interrompe prazo para livramento, mas pode importar nos requisitos subjetivos. Integrar LEP e vedações especiais atuais; não confundir com progressão.', 'Primário com bons antecedentes condenado a seis anos cumpriu exatamente dois: ainda não cumpriu MAIS de um terço na hipótese do inciso I.', 'Com mais de dois anos cumpridos, o requisito temporal pode mudar, mas ainda avaliar faltas, comportamento e demais condições; em hipótese legal de vedação, a fração não libera o benefício.', ['A fração sozinha basta? Não; requisitos são cumulativos.', 'Falta grave reinicia automaticamente esse prazo? Não, conforme Súmula 441; distinguir avaliação subjetiva.'],'Livramento condicional','Liberdade condicionada na execução, distinta de progressão e sursis.')
add(84,'Para o livramento, somam-se penas correspondentes a infrações diversas. A regra de soma não transforma todas as infrações numa espécie única nem apaga requisitos e vedações próprias.', ['Soma das penas para efeito do benefício.', 'Identificar a natureza de cada condenação.'], 'Não usar o teto de cumprimento do art. 75 como substituto automático de todos os cálculos. A soma não dispensa os requisitos do art. 83 e legislação especial.', 'Duas condenações são tratadas isoladamente para omitir pena relevante ao livramento.', 'Com ambas consideradas, ainda examinar frações e impedimentos pertinentes, sem concluir benefício automático.', ['O texto manda somar para esse efeito? Sim.', 'A soma elimina impedimentos especiais? Não; eles exigem integração.'],'Soma para livramento','Consideração conjunta das penas no regime do benefício.')
add(85,'A sentença especifica as condições do livramento. O benefício não é liberdade sem deveres; devem ser identificadas condições legais e aquelas fixadas legitimamente para o caso.', ['Condições devem ser especificadas.', 'Integração com a disciplina de execução.'], 'Não inventar condições arbitrárias nem supor que todas sejam idênticas às do sursis. Examinar lei, decisão e situação concreta.', 'O candidato chama livramento de dispensa de qualquer condição.', 'Se a sentença fixa condições legais, seu cumprimento importa, sem equivaler à suspensão do processo.', ['Existem condições especificadas? Sim; o artigo exige isso.', 'É o mesmo instituto do sursis? Não; verificar regime próprio.'],'Condição do livramento','Dever de observação fixado no benefício de execução.')
add(86,'A revogação obrigatória prevista exige condenação irrecorrível a pena privativa. Abrange crime durante o benefício e crime anterior, neste último com a integração do art. 84.', ['Condenação definitiva a pena privativa.', 'Distinguir crime anterior e cometido na vigência.'], 'Não equiparar mero indiciamento a condenação irrecorrível. Medidas provisórias de execução são outra análise, sem presumir decisão final.', 'O liberado é condenado definitivamente a pena privativa por crime cometido durante o benefício.', 'Se existe apenas investigação, não estão demonstrados os requisitos de revogação obrigatória deste artigo.', ['Indiciamento basta para essa hipótese definitiva? Não.', 'Crime anterior é irrelevante? Não; o inciso II o contempla com a remissão.'],'Revogação obrigatória','Consequência nas hipóteses e pressupostos específicos do artigo.')
add(87,'A revogação facultativa pode decorrer de descumprimento de obrigação ou condenação irrecorrível por crime/contravenção a pena não privativa. Não significa que qualquer notícia imponha revogação automática.', ['O juiz PODERÁ revogar.', 'Pena não privativa difere da hipótese do art. 86.'], 'Examinar prova, procedimento e decisão fundamentada. Facultativa não é obrigação universal nem dispensa das garantias.', 'Uma obrigação da sentença foi descumprida e o candidato afirma que o artigo manda obrigatoriamente revogar.', 'Se a condenação definitiva é a pena privativa, reavaliar a hipótese do art. 86, sem trocar os regimes.', ['O verbo legal indica faculdade? Sim.', 'A hipótese de pena não privativa é igual à do art. 86? Não; os artigos distinguem regimes.'],'Revogação facultativa','Possibilidade fundamentada, diferente da hipótese obrigatória.')
add(88,'Revogado o livramento, não se concede novamente aquele benefício; a regra de não descontar o tempo solto tem exceção quando a revogação decorre de condenação por crime anterior ao benefício.', ['Regra: não descontar tempo em liberdade.', 'Exceção: condenação por crime anterior.'], 'Não apagar a exceção nem estender a proibição a qualquer benefício futuro de qualquer condenação sem análise própria. Identificar o motivo da revogação.', 'O livramento foi revogado por condenação por crime anterior e a questão proíbe descontar o tempo solto sem ressalva.', 'Se o fundamento é crime na vigência, a exceção indicada não se aplica pela mesma razão.', ['Há exceção ao não desconto? Sim; crime anterior na hipótese legal.', 'O motivo da revogação importa? Sim; altera esse efeito.'],'Efeitos da revogação','Consequências condicionadas ao fundamento, não regra indiferenciada.')
add(89,'O texto impede declarar extinta a pena enquanto não transitar a sentença no processo por crime cometido durante o livramento. A aplicação exige integração com suspensão/revogação e seus marcos, não prorrogação indefinida por qualquer processo.', ['Crime cometido na vigência é o recorte.', 'Confrontar decisões e término do período de prova.'], 'Súmula 617/STJ: ausência de suspensão ou revogação antes do término do período de prova enseja extinção pelo cumprimento integral. Não usar o art. 89 isoladamente para autorizar revogação tardia universal.', 'Há processo por fato durante o benefício, mas nenhuma suspensão ou revogação até o término do período.', 'Se houve suspensão tempestiva, muda o pressuposto da Súmula 617; examinar o procedimento, sem presumir o mesmo resultado.', ['Qualquer processo autoriza espera indefinida? Não; recorte e marcos importam.', 'A Súmula 617 exige olhar a data da suspensão/revogação? Sim; antes do término.'],'Marco do período de prova','Data relevante à integração entre processo pendente e extinção.')
add(91,'A condenação torna certa a obrigação de indenizar e prevê perda de instrumentos ilícitos e produto/proveito, ressalvados lesado e terceiro de boa-fé. A perda de equivalentes tem condições quando o produto não é encontrado ou está no exterior.', ['Instrumento ilícito e produto/proveito são categorias diferentes.', 'Equivalentes: §§1º/2º; resguardar terceiros e procedimento.'], 'Não presumir que todo bem lícito usado no crime é perdido por esta alínea nem que o valor civil já esteja integralmente liquidado. A remissão à ADPF 569 não certifica aqui toda interpretação da decisão; integrar hipóteses especiais, inclusive art. 91-A.', 'Um instrumento cujo porte é lícito é confiscado apenas pela generalização da alínea a, sem hipótese especial identificada.', 'Se é produto do delito, examinar alínea b e direitos protegidos, em vez de exigir ilicitude intrínseca do objeto.', ['Toda ferramenta lícita entra automaticamente na alínea a? Não; a hipótese exige ilicitude indicada.', 'O terceiro de boa-fé pode ser ignorado? Não; há ressalva expressa.'],'Perdimento','Perda patrimonial nas hipóteses legais, distinta da apreensão provisória.')
add('91-a','Perda alargada considera incompatibilidade patrimonial em condenação por infração com pena máxima superior a seis anos de reclusão. Há requerimento expresso na denúncia, defesa da origem lícita e especificação na sentença; o §5º trata especialmente de instrumentos de organizações/milícias.', ['SUPERIOR a 6 anos, não exatamente seis.', 'MP requer na denúncia e indica diferença; sentença especifica valor/bens.', 'Lei 15.358, vigente em 25/3/2026: §5º inclui União, Estado ou DF conforme a Justiça.'], 'Não confiscar por mera acusação ou nome de facção. Identificar os requisitos e separar perda alargada do caput da hipótese especial do §5º; mudança gravosa não retroage e controle constitucional deve ser acompanhado, sem declarar toda controvérsia resolvida.', 'A infração tem pena máxima exatamente seis anos e a questão considera preenchido o requisito de superior a seis.', 'Com máxima superior a seis, ainda verificar condenação, pedido, diferença patrimonial, defesa e sentença.', ['Máxima de seis satisfaz superior a seis? Não.', 'O caput dispensa pedido expresso na denúncia? Não; o §3º exige.'],'Perda alargada','Hipótese patrimonial com pressupostos e garantias específicos.')
add(92,'Os efeitos específicos incluem cargo/função/mandato, poder familiar e direção de veículo, com pressupostos distintos. A regra exige declaração motivada, mas o §2º excepciona a automaticidade; em 2026 seu alcance foi ampliado a crimes do ECA expressamente listados.', ['Cargo: igual/superior a 1 ano na hipótese de abuso/dever; superior a 4 nos demais.', 'Lei 15.487, publicada e vigente em 7/8/2026: lista específica de crimes do ECA no §2º.', 'Lei 15.358, vigente em 25/3/2026: CNPJ 180 dias; reincidência e interdição comercial por 5 anos têm hipóteses próprias.'], 'Nem todos os efeitos são sempre automáticos, nem sempre dependem de declaração: distinguir §§1º/2º. Não estender a qualquer crime do ECA ou qualquer estabelecimento; observar lei no tempo e os pressupostos das hipóteses recentes.', 'O candidato diz que os efeitos do art. 92 nunca são automáticos, ignorando §2º e sua lista atual.', 'Fora da exceção, aplicar a regra de declaração motivada; não presumir automática perda de cargo por qualquer pena.', ['Nunca são automáticos? Não; o §2º traz exceções.', 'A ampliação de 2026 inclui todo crime do ECA? Não; há lista expressa de dispositivos.'],'Efeitos específicos','Consequências adicionais com requisitos e exceções próprias.')
add(93,'Reabilitação assegura sigilo dos registros de processo/condenação nas condições legais. Pode alcançar efeitos do art. 92, mas não permite reintegração à situação anterior nos incisos I e II.', ['Sentença definitiva e regime de reabilitação.', 'Vedação de reintegração nos incisos I/II.'], 'Não confundir sigilo com apagar o fato, absolver ou assegurar retorno automático ao cargo. Integrar arts. 94/95 e regime de registros.', 'Após reabilitação, o candidato afirma direito automático de reassumir o cargo perdido.', 'Se o pedido trata do sigilo, examinar essa proteção, distinguindo-a da reintegração proibida.', ['Reabilitar garante retorno ao cargo? Não; há vedação indicada.', 'É absolvição retroativa? Não; não transforma a condenação em absolvição.'],'Reabilitação','Instituto de sigilo e efeitos delimitados, com requisitos legais.')
add(94,'Reabilitação pode ser requerida após dois anos dos marcos legais, computados períodos de prova sem revogação, com domicílio no País, comportamento e reparação ou alternativas expressas. Indeferimento permite novo pedido com novos elementos.', ['Dois anos da extinção ou término, não necessariamente do trânsito.', 'Reparação: impossibilidade absoluta, renúncia da vítima ou novação são alternativas previstas.'], 'Não exigir novo biênio universal depois de indeferimento nem negar automaticamente por pobreza: identificar a impossibilidade e comprovação pertinentes. Não presumir que só o prazo basta.', 'O pedido negado é renovado com novos elementos e a questão exige esperar sempre mais dois anos.', 'Se não há novos elementos comprobatórios, falta requisito da renovação; tempo sozinho não os substitui.', ['O trânsito é sempre o único marco? Não; o artigo usa extinção/término.', 'Novo pedido exige sempre outro biênio? Não; o parágrafo permite a qualquer tempo com novos elementos.'],'Requisitos da reabilitação','Condições cumulativas e alternativas de reparação previstas.')
add(95,'Reabilitação é revogada de ofício ou por requerimento do MP quando há condenação definitiva como reincidente a pena que não seja multa. Investigação ou condenação exclusivamente pecuniária não preenche essa hipótese.', ['Decisão definitiva e condição de reincidente.', 'Pena que NÃO seja multa.'], 'Não revogar por mera acusação nem omitir a ressalva da multa. Verificar todos os pressupostos, não apenas a existência de novo fato.', 'A nova condenação definitiva, como reincidente, é exclusivamente a multa.', 'Se a pena não é multa e os demais requisitos se completam, examinar a hipótese de revogação.', ['Qualquer investigação basta? Não; exige condenação definitiva.', 'Só multa satisfaz essa hipótese? Não; o artigo a excepciona.'],'Revogação da reabilitação','Consequência com requisitos específicos, não cancelamento por notícia.')
add(96,'O CP enumera internação e tratamento ambulatorial, integrados à legislação de saúde mental e garantias. Extinta a punibilidade, não se impõe nem subsiste medida de segurança.', ['Duas espécies textuais.', 'Extinção da punibilidade impede imposição/subsistência.'], 'A enumeração histórica não dispensa Lei 10.216: cuidado adequado, recursos extra-hospitalares e garantias. Não transformar diagnóstico em confinamento automático; toda política/regulamentação não foi certificada aqui.', 'A punibilidade está extinta e a questão admite impor medida de segurança pelo mesmo fato apenas porque há diagnóstico.', 'Com punibilidade não extinta, ainda verificar imputabilidade, decisão e necessidade, sem concluir medida automática.', ['Extinta a punibilidade pode impor a medida pelo fato? Não; o parágrafo veda.', 'Diagnóstico sozinho define internação? Não; exige avaliação e regime de cuidado.'],'Medida de segurança','Resposta jurídico-terapêutica com pressupostos e limites, não pena perpétua.')
add(97,'O texto diferencia internação e tratamento e prevê mínimo de um a três anos, perícia e liberação condicional. Deve ser lido com limites constitucionais, Súmula 527/STJ e Lei 10.216; não ensina internação perpétua nem escolha automática apenas pelo nome da pena.', ['Mínimo fixado de 1 a 3 não é máximo universal de duração.', 'Perícia no termo mínimo e anualmente, ou a qualquer tempo por determinação.', 'Súmula 527: duração não deve ultrapassar máximo abstratamente cominado ao delito.'], 'Tempo indeterminado não autoriza perpetuidade. Necessidade clínica, modalidade adequada e garantias importam; Lei 10.216 exige insuficiência dos recursos extra-hospitalares para internação. Não se certifica toda regulamentação antimanicomial neste bloco.', 'A questão transforma a expressão tempo indeterminado em autorização de internação perpétua.', 'Se o tratamento é ambulatorial, internação posterior ainda exige necessidade curativa e garantias, não é automática por conveniência.', ['Um a três anos é sempre o teto? Não; o texto o chama prazo mínimo.', 'Pode ultrapassar sem limite o máximo do delito segundo Súmula 527? Não.'],'Limites da medida','Prazo e cuidado integrados à jurisprudência e legislação de saúde.')
add(98,'No semi-imputável que necessita de especial tratamento curativo, a pena privativa pode ser substituída por medida adequada, com mínimo de um a três anos e remissões ao art. 97. Não é substituição obrigatória para todo diagnóstico.', ['Hipótese: art. 26, parágrafo único.', 'Necessidade de especial tratamento; poderá substituir.'], 'Distinguir redução por capacidade diminuída de substituição curativa. Integrar Súmula 527 e Lei 10.216; não somar automaticamente pena e medida como duas punições integrais pelo mesmo título.', 'Há capacidade diminuída, mas a questão impõe internação automaticamente sem avaliar necessidade curativa.', 'Com necessidade demonstrada, examinar a possibilidade e modalidade adequada, preservando direitos e limites.', ['Todo diagnóstico impõe substituição? Não; há pressupostos próprios.', 'O artigo usa faculdade e necessidade? Sim; pode substituir se necessitar especial tratamento.'],'Semi-imputabilidade','Capacidade diminuída na hipótese legal, distinta de incapacidade inteira.')
add(99,'O internado tem direito a estabelecimento adequado com características hospitalares e tratamento. Custódia não permite negar assistência ou transformar a medida em mero isolamento sem cuidados.', ['Tratamento é dever legal.', 'Integração com Lei 10.216 e direitos de saúde mental.'], 'Não concluir que qualquer cela sem atendimento satisfaz o artigo. A denominação do local não substitui condições reais e proteção de direitos; não certificar toda rede/regulamentação nesta revisão.', 'A instituição apenas isola a pessoa e não oferece tratamento, alegando que a custódia basta.', 'Com cuidado adequado, ainda avaliar continuidade, necessidade e garantias, sem presumir confinamento vitalício.', ['Só isolar cumpre o dever? Não; o texto exige tratamento.', 'Características hospitalares dispensam assistência real? Não; ambas devem ser efetivas.'],'Direito ao tratamento','Garantia de cuidado e adequação institucional.')
add(100,'A ação penal é pública como regra, salvo lei expressa de iniciativa privada. MP promove a pública; representação e requisição são condições quando exigidas. A privada subsidiária cabe na inércia legal do MP, não por mera discordância da vítima.', ['Queixa é peça da iniciativa privada; denúncia da pública.', 'Subsidiária: denúncia não oferecida no prazo legal.', 'Morte/ausência: cônjuge, ascendente, descendente ou irmão no §4º.'], 'Não transformar toda ação pública em condicionada nem toda discordância de arquivamento em direito a queixa subsidiária. Integrar CPP e legislação especial; vínculo com vítima não transfere titularidade de qualquer ação.', 'A vítima discorda de atuação tempestiva do MP e presume cabimento automático da queixa subsidiária.', 'Se há inércia e transcurso do prazo legal, examinar o fundamento específico e os demais requisitos.', ['Toda ação pública exige representação? Não; apenas quando lei exige.', 'Subsidiária decorre simplesmente de discordância? Não; o §3º usa inércia no prazo.'],'Titularidade da ação','Legitimação para promover ação conforme o regime legal.')
add(101,'No crime complexo, a ação será pública se algum fato integrante que constitui crime tem iniciativa do MP, nos termos do artigo. O enquadramento exige identificar elementos do tipo, não apenas dizer que o caso é complicado.', ['Fatos constitutivos de crime como elemento/circunstância do tipo.', 'Iniciativa pública de algum integrante é o requisito indicado.'], 'Complexo é categoria jurídica, não sinônimo de investigação difícil. Integrar o tipo específico atual; não usar o artigo para contrariar regime especial sem confronto.', 'O candidato chama uma apuração difícil de crime complexo e aplica o artigo sem analisar o tipo.', 'Se o tipo integra fatos criminosos e há iniciativa pública no recorte legal, muda o fundamento da análise.', ['Basta investigação difícil? Não; exige estrutura do tipo.', 'O tipo específico deve ser conferido? Sim; a categoria não dispensa seu regime atual.'],'Crime complexo','Tipo que integra fatos criminosos, não dificuldade prática.')
add(102,'Pela regra geral do CP, a representação torna-se irretratável depois de oferecida a denúncia. Oferecimento não é recebimento judicial; hipóteses especiais devem ser estudadas em sua própria disciplina.', ['Marco geral: OFERECIMENTO.', 'Não confundir representação, queixa e perdão.'], 'Maria da Penha, art. 16, tem disciplina especial para ações condicionadas; não transportar automaticamente o marco geral nem criar representação em crime de ação incondicionada.', 'Na regra geral, a denúncia foi oferecida mas ainda não recebida e a questão admite retratação só por não haver recebimento.', 'Se incide disciplina especial aplicável, confrontar seus requisitos em vez de repetir o marco geral sem ressalva.', ['O CP usa recebimento como marco geral? Não; usa oferecimento.', 'A regra torna toda ação condicionada? Não; depende do regime do crime.'],'Irretratabilidade','Impossibilidade de retirar a representação após o marco aplicável.')
add(103,'O prazo geral para queixa/representação é seis meses dos marcos indicados, salvo regra expressa diversa. Lei 15.438/2026 trouxe doze meses no âmbito de violência doméstica e familiar contra mulher; a mudança não transforma ação incondicionada em condicionada.', ['Geral: 6 meses desde conhecimento do AUTOR, não necessariamente do fato.', 'Subsidiária: fim do prazo para denúncia.', 'Parágrafo incluído em 2026: 12 meses; publicação/vigência em 19/6/2026.'], 'Identificar necessidade de representação/queixa, regra especial e lei no tempo. Ampliação prejudicial não reabre automaticamente decadência já consumada nem autoriza retroagir por estar no compilado atual. Não aplicar seis meses indistintamente a toda violência doméstica.', 'A questão sobre regime atual de ação condicionada em violência doméstica ignora o parágrafo e aplica sempre seis meses.', 'Se a ação é pública incondicionada, não inventar condição de representação apenas para aplicar os doze meses.', ['Todo caso doméstico exige representação? Não; verificar o tipo.', 'O prazo novo permite reabrir automaticamente decadência consumada? Não; exige análise temporal e irretroatividade prejudicial.'],'Decadência','Perda do direito por não exercer a iniciativa/condição no prazo aplicável.')
add(104,'Renúncia expressa ou tácita impede exercício do direito de queixa. Ato incompatível pode configurar renúncia tácita, mas receber indenização não a implica por si segundo a regra do CP.', ['Renúncia do direito de queixa precede seu exercício.', 'Indenização: ressalva expressa do CP.'], 'Não confundir renúncia com perdão após início da ação. Regimes especiais de composição civil exigem confronto próprio; não afirmar que todo pagamento sempre renuncia ou nunca afeta qualquer procedimento.', 'A vítima recebe indenização e a questão presume renúncia tácita apenas por esse recebimento, na regra geral do CP.', 'Se há outro ato incompatível demonstrado ou regime especial de composição, reavaliar seus pressupostos, sem generalizar a ressalva.', ['Indenização por si implica renúncia tácita no CP? Não; há ressalva.', 'Renúncia e perdão são o mesmo momento? Não; distinguir antes/depois do exercício.'],'Renúncia','Abandono do direito de queixa antes de exercê-lo, na hipótese aplicável.')
add(105,'O perdão do ofendido impede prosseguimento nos crimes que somente se processam por queixa, integrado à aceitação e limites do art. 106. Não autoriza extinguir toda ação pública pela vontade isolada da vítima.', ['Recorte: ação de iniciativa privada exclusiva.', 'Perdão deve ser lido com art. 106.'], 'Não confundir com perdão judicial, retratação de representação ou renúncia anterior à queixa. A frase não elimina requisito de aceitação pertinente.', 'Em ação pública, a vítima declara perdão e o candidato conclui extinção automática com base no art. 105.', 'Na ação privada exclusiva, examinar perdão e aceitação, não considerar a declaração sozinha universalmente suficiente.', ['Serve indistintamente para ação pública? Não; o recorte é específico.', 'Dispensa leitura do art. 106? Não; integra aceitação e limites.'],'Perdão do ofendido','Instituto da ação privada, distinto do perdão judicial.')
